//! One normal Root entry opens one existing session, loads original files,
//! consumes one generation/task purpose, and retains that same host for V3.
//! The original descriptor parser claims ALL numbers before any owner opens.

use std::collections::{BTreeMap, BTreeSet};
use std::ffi::{OsStr, OsString};
use std::fs::File;
use std::os::fd::OwnedFd;
use std::os::unix::fs::MetadataExt;
use std::os::unix::net::{UnixDatagram, UnixStream};
use std::path::PathBuf;

use codex_hepta_agentd::{CellQ24ModelFilesV1, PreparedHostAuthoritySession,
    RootHostInitialGenerationFilesV1, RootHostQ24TaskFilesV1, PreparedRootHostInitialGenerationV1,
    RootHostOriginalTaskLearningFilesV1, RootResidentCandidateEnrollmentInputsV3};

#[derive(Clone, Copy)]
pub(super) enum Command { Fresh, Recover }

const REQUIRED_FDS: [&str; 26] = [
    "--owner-pidfd", "--generation-registry-fd", "--generation-payload-fd",
    "--withdrawal-snapshot-fd", "--generation-journal-fd", "--generation-witness-fd",
    "--task-source-journal-fd", "--task-source-witness-fd", "--task-cell-journal-fd",
    "--task-cell-witness-fd", "--task-inference-control-fd", "--task-model-base-fd",
    "--task-model-encoder-fd", "--task-model-heads-fd", "--root-production-handoff-fd",
    "--root-original-task-handoff-fd", "--task-root-pidfd", "--candidate-stage-handoff-fd",
    "--resident-enrollment-handoff-fd", "--resident-root-pidfd", "--resident-consumer-pidfd",
    "--material-source-stream-fd", "--material-consumer-pidfd", "--baseline-base-fd",
    "--baseline-encoder-fd", "--baseline-heads-fd",
];
const OPTIONAL_FDS: [&str; 4] = ["--task-model-organ-fd", "--task-model-cell-fd",
    "--baseline-organ-fd", "--baseline-cell-fd"];

pub(super) fn run(mut options: BTreeMap<OsString, OsString>, command: Command)
    -> Result<(), Box<dyn std::error::Error>>
{
    let mut take_path = |key: &str| options.remove(OsStr::new(key)).map(PathBuf::from)
        .ok_or("missing required original Root loading option");
    let config = take_path("--config")?;
    let registration = take_path("--registration")?;
    let generation_deployment = take_path("--generation-deployment")?;
    let task_deployment = take_path("--task-deployment")?;
    let service_deployment = take_path("--task-learning-service")?;
    let readback = match command {
        Command::Fresh => None,
        Command::Recover => Some(take_path("--resident-readback")?),
    };
    let mut raw = Vec::new();
    for key in REQUIRED_FDS {
        raw.push((key, options.remove(OsStr::new(key)).ok_or("missing required original descriptor slot")?));
    }
    for key in OPTIONAL_FDS {
        if let Some(value) = options.remove(OsStr::new(key)) { raw.push((key, value)); }
    }
    if !options.is_empty() { return Err("unknown original Root task loading option".into()); }
    let mut claimed = BTreeSet::new();
    let mut descriptors = BTreeMap::new();
    for (key, value) in raw {
        descriptors.insert(key, super::inherited_descriptor(&value, &mut claimed)?);
    }
    let mut files = Descriptors(descriptors);
    let owner_pidfd = files.take_original_descriptor("--owner-pidfd")?;
    let generation = RootHostInitialGenerationFilesV1 {
        registry_snapshot: files.file("--generation-registry-fd")?,
        selected_payload: files.file("--generation-payload-fd")?,
        withdrawal_snapshot: files.file("--withdrawal-snapshot-fd")?,
        target_journal: files.file("--generation-journal-fd")?,
        target_witness: files.file("--generation-witness-fd")?,
    };
    let task = RootHostQ24TaskFilesV1 {
        source_journal: files.file("--task-source-journal-fd")?,
        source_witness: files.file("--task-source-witness-fd")?,
        cell_journal: files.file("--task-cell-journal-fd")?,
        cell_witness: files.file("--task-cell-witness-fd")?,
        inference_control: files.file("--task-inference-control-fd")?,
        model: CellQ24ModelFilesV1 {
            base: files.file("--task-model-base-fd")?, encoder: files.file("--task-model-encoder-fd")?,
            heads: files.file("--task-model-heads-fd")?,
            organ_adapter: files.optional_file("--task-model-organ-fd"),
            cell_adapter: files.optional_file("--task-model-cell-fd"),
        },
    };
    let service = RootHostOriginalTaskLearningFilesV1 {
        production_handoff: UnixDatagram::from(files.take_original_descriptor("--root-production-handoff-fd")?),
        task_handoff: UnixDatagram::from(files.take_original_descriptor("--root-original-task-handoff-fd")?),
        original_task_root_pidfd: files.take_original_descriptor("--task-root-pidfd")?,
        resident: RootResidentCandidateEnrollmentInputsV3 {
            stage_handoff: UnixDatagram::from(files.take_original_descriptor("--candidate-stage-handoff-fd")?),
            enrollment_handoff: UnixDatagram::from(files.take_original_descriptor("--resident-enrollment-handoff-fd")?),
            original_root_pidfd: files.take_original_descriptor("--resident-root-pidfd")?,
            original_consumer_pidfd: files.take_original_descriptor("--resident-consumer-pidfd")?,
            baseline_files: CellQ24ModelFilesV1 {
                base: files.file("--baseline-base-fd")?, encoder: files.file("--baseline-encoder-fd")?,
                heads: files.file("--baseline-heads-fd")?,
                organ_adapter: files.optional_file("--baseline-organ-fd"),
                cell_adapter: files.optional_file("--baseline-cell-fd"),
            },
        },
        material_stream: UnixStream::from(files.take_original_descriptor("--material-source-stream-fd")?),
        original_material_pidfd: files.take_original_descriptor("--material-consumer-pidfd")?,
    };
    if !files.0.is_empty() { return Err("unconsumed original descriptor slot".into()); }
    require_distinct_writer_files(&generation, &task, &service.resident.baseline_files)?;
    // This original open is the only session/issuer opening in the flow.
    // The task and resident branches subsequently use its retained instances.
    let session = PreparedHostAuthoritySession::open(&config, &registration, owner_pidfd)?;
    match command {
        Command::Fresh => {
            let mut generation = session.prepare_original_initial_generation_from_files(&generation_deployment, generation)?;
            PreparedRootHostInitialGenerationV1::publish_original_generation(&mut generation)?;
            let task = generation.prepare_original_root_task_from_files(&task_deployment, task)?;
            task.serve_loaded_original_task_and_resident(&service_deployment, service)?;
        }
        Command::Recover => {
            let generation = session.recover_original_initial_generation_from_files(&generation_deployment, generation)?;
            let task = generation.recover_original_root_task_from_files(&task_deployment, task)?;
            let readback = readback.ok_or("the original resident readback authorization is missing")?;
            task.recover_loaded_original_task_and_resident(&service_deployment, service, &readback)?;
        }
    }
    Ok(())
}

struct Descriptors(BTreeMap<&'static str, OwnedFd>);
impl Descriptors {
    fn take_original_descriptor(&mut self, name: &'static str) -> Result<OwnedFd, Box<dyn std::error::Error>> {
        self.0.remove(name).ok_or_else(|| "original descriptor was already consumed".into())
    }
    fn file(&mut self, name: &'static str) -> Result<File, Box<dyn std::error::Error>> {
        Ok(File::from(self.take_original_descriptor(name)?))
    }
    fn optional_file(&mut self, name: &'static str) -> Option<File> { self.0.remove(name).map(File::from) }
}

fn require_distinct_writer_files(generation: &RootHostInitialGenerationFilesV1,
    task: &RootHostQ24TaskFilesV1, baseline: &CellQ24ModelFilesV1,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut writers = BTreeSet::new();
    for file in [&generation.target_journal, &generation.target_witness, &task.source_journal,
        &task.source_witness, &task.cell_journal, &task.cell_witness, &task.inference_control]
    {
        let metadata = file.metadata()?;
        if !writers.insert((metadata.dev(), metadata.ino())) {
            return Err("one original writer file cannot serve two owner roles".into());
        }
    }
    let mut readers = vec![&generation.registry_snapshot, &generation.selected_payload,
        &generation.withdrawal_snapshot, &task.model.base, &task.model.encoder, &task.model.heads,
        &baseline.base, &baseline.encoder, &baseline.heads];
    readers.extend([task.model.organ_adapter.as_ref(), task.model.cell_adapter.as_ref(),
        baseline.organ_adapter.as_ref(), baseline.cell_adapter.as_ref()].into_iter().flatten());
    for file in readers {
        let metadata = file.metadata()?;
        if writers.contains(&(metadata.dev(), metadata.ino())) {
            return Err("an original writer file cannot alias a read-only input".into());
        }
    }
    Ok(())
}

//! The loaded callback stays inside this private subtree. Only the original
//! remote task pump and its strengthened feature control can consume it.
//! All normally returning branches join the actual owned service threads.

use std::os::fd::OwnedFd;
use std::os::unix::net::{UnixDatagram, UnixStream};
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use serde::Deserialize;
use tokio_util::sync::CancellationToken;

use super::PreparedRootHostLoadedQ24TaskV1;
use crate::{AgentdError, RootResidentCandidateEnrollmentInputsV3,
    RootResidentCandidateEnrollmentServiceV3, PreparedRootHostCircuitTaskV1,
    PreparedRootMaterialSourceHostV1};
use crate::authority_host_config::read_root_json;
use crate::authority_host_runtime::{OriginalTaskResidentInputs,
    OriginalTaskResidentPaths, OriginalTaskResidentPurpose};

/// Supervisor-owned descriptors only. Material must be a distinct actual
/// non-Root peer; an inherited socketpair created as Root cannot attest it.
/// The ten original roles arrive through the unchanged separate 21-right frame.
pub struct RootHostOriginalTaskLearningFilesV1 {
    pub production_handoff: UnixDatagram,
    pub task_handoff: UnixDatagram,
    pub original_task_root_pidfd: OwnedFd,
    pub resident: RootResidentCandidateEnrollmentInputsV3,
    pub material_stream: UnixStream,
    pub original_material_pidfd: OwnedFd,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ServiceFile {
    schema_version: u32,
    purpose: String,
    consumer_state_root: PathBuf,
    task_socket: PathBuf,
    loan_socket: PathBuf,
    task_nonce: [u8; 16],
    resident_deployment: PathBuf,
    resident_evidence_trust: PathBuf,
    prefreeze_disclosure: PathBuf,
}

impl PreparedRootHostLoadedQ24TaskV1 {
    /// Run the real ordinary task and enroll its later original candidate on
    /// the SAME Root session. This requires the real post-A Generator/Observer
    /// intake and signed freeze supplied by their owners; no data is invented
    /// when those owners have not completed that distinct stage.
    pub fn serve_loaded_original_task_and_resident(
        self, service_file: &Path, files: RootHostOriginalTaskLearningFilesV1,
    ) -> Result<(), AgentdError> {
        self.run_loaded_original_services(service_file, files, OriginalTaskResidentPurpose::Fresh)
    }

    /// The original existing task and V3 checkpoint remain readback-only where
    /// their original factories require it. Failure never selects Fresh again.
    pub fn recover_loaded_original_task_and_resident(
        self, service_file: &Path, files: RootHostOriginalTaskLearningFilesV1,
        original_resident_readback: &Path,
    ) -> Result<(), AgentdError> {
        self.run_loaded_original_services(service_file, files,
            OriginalTaskResidentPurpose::Readback(original_resident_readback.to_owned()))
    }

    fn run_loaded_original_services(
        mut self, service_file: &Path, files: RootHostOriginalTaskLearningFilesV1,
        purpose: OriginalTaskResidentPurpose,
    ) -> Result<(), AgentdError> {
        self.clock_status.require_healthy()?;
        self.read_loaded_original_root_task_generation()?;
        let specification: ServiceFile = read_root_json(service_file)?;
        if specification.schema_version != 1
            || specification.purpose != "hepta.root.same-task-material-resident.service.v1"
            || specification.task_nonce == [0; 16]
        { return Err(protocol("original Root service purpose differs")); }
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
        let (material_host, followups) = self.task.take_original_loader_followups()?;
        let startup_end = followups.require_startup_end(Instant::now() + Duration::from_secs(30))?;
        self.clock_status.require_healthy()?;
        let RootHostOriginalTaskLearningFilesV1 { production_handoff, task_handoff,
            original_task_root_pidfd, resident, material_stream, original_material_pidfd } = files;
        let (material_registration, prefreeze) = followups.prepare_prefreeze(
            &specification.prefreeze_disclosure, &specification.resident_evidence_trust,
            material_stream, original_material_pidfd, startup_end,
        )?;
        self.clock_status.require_healthy()?;
        let paths = OriginalTaskResidentPaths { deployment: specification.resident_deployment };
        let clock_status = self.clock_status;
        let mut task = self.task;
        std::thread::scope(|scope| {
            let (task_done_sender, mut task_done) = tokio::sync::oneshot::channel();
            let task_thread = scope.spawn(move || {
                let result = PreparedRootHostCircuitTaskV1::handoff_and_serve_original_root_circuit_task_before(
                    &mut task, production_handoff, task_handoff, original_task_root_pidfd,
                    &specification.consumer_state_root, specification.task_socket,
                    specification.loan_socket, specification.task_nonce, startup_end,
                );
                let _ = task_done_sender.send(());
                result
            });
            // Start the only Source lane before the late signed freeze is
            // required. The same client later enters the actual Material pair;
            // this export cannot also create a post-freeze Source connection.
            let (material_done_sender, mut material_done) = tokio::sync::oneshot::channel();
            let material_thread = scope.spawn(move || {
                let result = PreparedRootMaterialSourceHostV1::serve_original_prefreeze(material_host, material_registration);
                let _ = material_done_sender.send(());
                result
            });
            let work_result = runtime.block_on(async {
                let mut terminate = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())?;
                let prepare = async {
                    let RootResidentCandidateEnrollmentInputsV3 { stage_handoff, enrollment_handoff,
                        original_root_pidfd, original_consumer_pidfd, baseline_files } = resident;
                    // Readability only wakes the receiver. The complete
                    // original frame, Root pin, purpose, recipient and roles
                    // must authenticate before any late deployment is read.
                    let stage_handoff = wait_original_stage_message(stage_handoff, startup_end).await?;
                    let remaining = startup_end.checked_duration_since(Instant::now())
                        .filter(|value| !value.is_zero()).ok_or_else(|| protocol("original stage deadline elapsed"))?;
                    let stage_transport = crate::root_production_handoff::receive_original_candidate_stage_transport(
                        stage_handoff, remaining)?;
                    clock_status.require_healthy()?;
                    let original = OriginalTaskResidentInputs {
                        stage_transport, enrollment_handoff, original_root_pidfd,
                        original_consumer_pidfd, baseline_files,
                    };
                    let prepared = followups.prepare_resident(paths, original, &prefreeze, purpose, startup_end)?;
                    clock_status.require_healthy()?;
                    let service = prepared.enroll().await?;
                    followups.require_original_task_followups()?;
                    prefreeze.require_original_prefreeze_trust()?;
                    clock_status.require_healthy()?;
                    Ok::<_, AgentdError>(service)
                };
                tokio::pin!(prepare);
                let resident = tokio::select! {
                    biased;
                    value = &mut prepare => value?,
                    _ = &mut task_done => return Err(protocol("task service ended before resident enrollment; same-operation readback required")),
                    _ = &mut material_done => return Err(protocol("original Source service ended before resident enrollment; same-operation readback required")),
                    signal = tokio::signal::ctrl_c() => {
                        return merge_results(signal.map_err(AgentdError::from),
                            Err(protocol("original enrollment interrupted; effects Unknown, same-operation readback required")));
                    }
                    _ = terminate.recv() => return Err(protocol("original enrollment terminated; effects Unknown, same-operation readback required")),
                };
                let cancellation = CancellationToken::new();
                let resident_work = RootResidentCandidateEnrollmentServiceV3::run(resident, cancellation.clone());
                tokio::pin!(resident_work);
                let result = tokio::select! {
                    biased;
                    value = &mut resident_work => value,
                    _ = &mut task_done => {
                        cancellation.cancel();
                        merge_results(resident_work.await, Err(protocol("task service ended while candidate service was active")))
                    }
                    _ = &mut material_done => {
                        cancellation.cancel();
                        merge_results(resident_work.await, Err(protocol("Material service ended while candidate service was active")))
                    }
                    signal = tokio::signal::ctrl_c() => {
                        cancellation.cancel();
                        let result = resident_work.await;
                        merge_results(merge_results(result, signal.map_err(AgentdError::from)),
                            Err(protocol("original services interrupted; effects Unknown")))
                    }
                    _ = terminate.recv() => {
                        cancellation.cancel();
                        merge_results(resident_work.await, Err(protocol("original services terminated; effects Unknown")))
                    }
                };
                merge_results(merge_results(result, followups.require_original_task_followups()), prefreeze.require_original_prefreeze_trust())
            });
            // Join actual submitted work, including error paths. No timeout,
            // abort or dropped future is relabeled as a completed thread.
            // Deadlines reject late results. Synchronous original I/O may
            // still block; no physical termination bound is asserted here.
            let task_result = task_thread.join().map_err(|_| protocol("original task service panicked; effects Unknown"))
                .and_then(|value| value.map(|_| ()));
            let material_result = material_thread.join().map_err(|_| protocol("original Material service panicked; effects Unknown"))
                .and_then(|value| value.map(|_| ()));
            merge_results(merge_results(merge_results(work_result, task_result), material_result),
                clock_status.require_healthy())
        })
    }
}

async fn wait_original_stage_message(socket: UnixDatagram, end: Instant) -> Result<UnixDatagram, AgentdError> {
    let remaining = end.checked_duration_since(Instant::now()).filter(|value| !value.is_zero())
        .ok_or_else(|| protocol("original stage startup ended"))?;
    crate::root_production_handoff::root_pair(&socket, remaining.min(Duration::from_secs(30)))?;
    socket.set_nonblocking(true)?;
    let original = tokio::io::unix::AsyncFd::new(socket)?;
    let ready = tokio::time::timeout_at(end.into(), original.readable()).await
        .map_err(|_| protocol("original stage handoff deadline elapsed"))??;
    drop(ready);
    let socket = original.into_inner();
    socket.set_nonblocking(false)?;
    if Instant::now() >= end { return Err(protocol("original stage handoff ended")); }
    Ok(socket)
}

fn merge_results(first: Result<(), AgentdError>, second: Result<(), AgentdError>) -> Result<(), AgentdError> {
    match (first, second) {
        (Ok(()), Ok(())) => Ok(()),
        (Err(error), Ok(())) | (Ok(()), Err(error)) => Err(error),
        (Err(first), Err(second)) => Err(protocol(format!("{first}; additional original failure: {second}"))),
    }
}

fn protocol(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::Protocol(format!("loaded original task assembly: {error}"))
}

//! Root's once-only late enrollment and original candidate service composition.

use super::*;
use std::time::Duration;
use crate::HostAuthorityServiceConfig;
use crate::authority_host_runtime::listeners::resident::ResidentListener;
use crate::authority_host_runtime::listeners::resident::ResidentSocketGuard;

#[path = "authority_host_resident_enrollment_wire.rs"]
mod wire;
#[path = "authority_host_resident_enrollment_connect.rs"]
mod connect;
pub(crate) use connect::connect_original_resident_enrollment;

#[path = "authority_host_task_resident_enrollment.rs"]
mod original_task;
pub(crate) use original_task::{OriginalTaskResidentInputs, OriginalTaskResidentPaths,
    OriginalTaskResidentPrepared, OriginalTaskResidentPurpose, prepare_original_task_resident,
    OriginalTaskPrefreezeState, prepare_original_task_prefreeze};

/// No stream created before the daemon's credential drop is accepted here.
/// Root creates one protected listener; the actual daemon connects after A.
pub struct RootResidentCandidateEnrollmentInputsV3 {
    pub stage_handoff: UnixDatagram,
    pub enrollment_handoff: UnixDatagram,
    pub original_root_pidfd: OwnedFd,
    pub original_consumer_pidfd: OwnedFd,
    pub baseline_files: CellQ24ModelFilesV1,
}

pub async fn prepare_host_resident_candidate_enrollment_v3(
    config_file: &Path,
    deployment_file: &Path,
    trusted_evidence_file: &Path,
    original: RootResidentCandidateEnrollmentInputsV3,
) -> io::Result<RootResidentCandidateEnrollmentServiceV3> {
    prepare_enrollment(config_file, deployment_file, trusted_evidence_file, original, Purpose::Fresh).await
}

pub async fn recover_host_resident_candidate_enrollment_v3(
    config_file: &Path,
    deployment_file: &Path,
    trusted_evidence_file: &Path,
    original: RootResidentCandidateEnrollmentInputsV3,
    readback_file: &Path,
) -> io::Result<RootResidentCandidateEnrollmentServiceV3> {
    prepare_enrollment(config_file, deployment_file, trusted_evidence_file, original, Purpose::Readback(readback_file)).await
}

async fn prepare_enrollment(
    config_file: &Path,
    deployment_file: &Path,
    trusted_evidence_file: &Path,
    original: RootResidentCandidateEnrollmentInputsV3,
    purpose: Purpose<'_>,
) -> io::Result<RootResidentCandidateEnrollmentServiceV3> {
    // SAFETY: both calls inspect only actual current credentials.
    if unsafe { libc::getuid() } != 0 || unsafe { libc::geteuid() } != 0 {
        return Err(io::Error::other("original Root resident process required"));
    }
    let config: HostAuthorityServiceConfig = read_root_json(config_file)?;
    config.required_bind.verify()?;
    let trust = trust::OriginalHostTrust::read(trusted_evidence_file)?;
    let RootResidentCandidateEnrollmentInputsV3 {
        stage_handoff, enrollment_handoff, original_root_pidfd,
        original_consumer_pidfd, baseline_files,
    } = original;
    let baseline = Arc::new(LoadedCellQ24ModelV1::open_files(baseline_files).map_err(io::Error::other)?);
    let inputs::OriginalDeployment { profile, inputs, consumer, handoff_timeout, enrollment_profile } =
        inputs::OriginalDeployment::read(deployment_file, &trust, baseline)?;
    let (peer, uid, timeout, lifetime) = consumer.into_peer();
    if uid != config.peer_uid || matches!(config.peer_gid, 0 | u32::MAX) {
        return Err(io::Error::other("resident recipient differs from original host config"));
    }
    let recipient = wire::Process::from_peer(&peer);
    recipient.require_original()?;
    crate::authority_host_runtime::verify_process_credentials(peer.pid, uid, config.peer_gid)?;
    crate::root_production_handoff::require_original_resident_process_pin(&original_consumer_pidfd, peer.pid)
        .map_err(io::Error::other)?;
    let now = wire::now_ns()?;
    let connect_before_ns = now.checked_add(u64::try_from(handoff_timeout.as_nanos()).map_err(io::Error::other)?)
        .ok_or_else(|| io::Error::other("resident handoff deadline overflow"))?;
    let session_end_ns = now.checked_add(u64::try_from(lifetime.as_nanos()).map_err(io::Error::other)?)
        .ok_or_else(|| io::Error::other("resident session deadline overflow"))?;
    let connect_end = wire::absolute(connect_before_ns, Duration::from_secs(30))?;
    let session_end = wire::absolute(session_end_ns, Duration::from_secs(300))?;
    let (authorization, readback) = match purpose {
        Purpose::Fresh => (wire::Authorization::Fresh, None),
        Purpose::Readback(path) => {
            let value: ReadbackFile = read_root_json(path)?;
            if value.schema_version != 3
                || value.purpose != "hepta.host-resident-learning.readback-deployment.v3"
            { return Err(io::Error::other("resident readback purpose differs")); }
            let authorization = wire::Authorization::Readback { intent: value.intent.clone(), lease: value.lease.clone() };
            let original = RootResidentLearningReadbackAuthorizationV3::from_original_root(&profile, value.intent, value.lease)?;
            (authorization, Some(original))
        }
    };
    let handoff = crate::receive_root_candidate_stage_handoff(stage_handoff, &profile, wire::remaining(connect_end)?)
        .map_err(io::Error::other)?;
    // After this call fails or its ACK is uncertain, only explicit readback of
    // the same operation is legal. No listener/send failure restores freshness.
    let binding = profile.binding();
    // Use the same concrete config already checked for recipient and listener
    // custody. Reuse the original open-only issuer factory without a second
    // path read that could select a different Root configuration.
    let super::super::OriginalHostIssuerCustodyV3 { issuer, leases, root, .. } =
        super::super::open_original_issuer_custody(&config)?;
    let registration = match readback {
        Some(readback) => RootResidentLearningRegistrationV3::recover_original_root(
            root, issuer, Arc::new(leases), profile, readback,
        )?,
        None => RootResidentLearningRegistrationV3::register_original_root(
            root, issuer, Arc::new(leases), profile,
        )?,
    };
    wire::remaining(connect_end)?;
    let listener = ResidentListener::bind_original(&config, binding)?;
    let (path, device, inode) = listener.original_node();
    let packet = wire::Packet {
        schema_version: 3, purpose: wire::PURPOSE.into(), root: wire::Process::current()?,
