pub(super) fn open_registered_issuer(
    config: &HostAuthorityServiceConfig,
) -> io::Result<(
    Arc<HostAuthorityClock>,
    AuthorityLeaseRegistry,
    Arc<DeploymentFinalUseIssuer>,
)> {
    let OriginalHostIssuerCustodyV3 {
