    /// bootstrap at the original fixed-lane listener barrier. The callback
    /// must only release that already prepared handoff; no new owner is opened
    /// and every original peer, deadline and no-retry check remains in force.
    pub fn launch_native_with_ready(
        self,
        config_file: &Path,
        registration_file: &Path,
        profile_file: &Path,
        ready: impl FnOnce() -> io::Result<()>,
    ) -> io::Result<()> {
        let (config, profile) = crate::authority_host_native_launch::inputs(
            config_file,
            registration_file,
            profile_file,
            &self.owner_pidfd,
        )?;
        let registration: HostAuthorityRegistration = read_root_json(registration_file)?;
        self.service
            .check_logind_binding(&profile.original_human_binding())?;
        if serde_json::to_vec(&config).map_err(io::Error::other)?
            != serde_json::to_vec(&self.config).map_err(io::Error::other)?
            || serde_json::to_vec(&registration).map_err(io::Error::other)?
                != serde_json::to_vec(&self.registration).map_err(io::Error::other)?
        {
            return Err(io::Error::other(
                "native launch changed the retained original Root inputs",
            ));
        }
        crate::authority_host_native_launch::launch_prepared_native_with_ready(
            self,
            config,
            profile,
            profile_file,
            ready,
        )
    }

    fn serve_selected(
        self,
        text_ui: Option<(&Path, OwnedFd)>,
        ready: impl FnOnce() -> io::Result<()>,
    ) -> io::Result<()> {
        let Self {
            config,
            registration,
            owner_pidfd,
            service,
            root_admin,
            learning,
            ..
        } = self;
        // Bind the dedicated optional lane before either five-lane ready
        // callback can release the child. Its accept loop runs independently.
        let learning = learning
            .map(|owner| learning::BoundLearning::bind(owner, &config))
            .transpose()?;
        if text_ui.is_some()
            && config.issuer_record_profile
                != crate::authority_host_config::HostIssuerRecordProfile::TextRecovery
        {
            return Err(io::Error::other(
                "native text requires the explicit text_recovery issuer record profile",
            ));
        }
        if let Some((text_file, ui_pidfd)) = text_ui {
            let text: crate::HostAuthorityTextUiRegistration = read_root_json(text_file)?;
            if text.peer_uid != config.peer_uid {
                return Err(io::Error::other(
                    "text UI must share the registered Agentd owner UID for its existing private ingress",
                ));
            }
            text.validate(&service)?;
            let service = service.with_live_human_text(text.clone(), ui_pidfd.try_clone()?)?;
            if [
                &config.sockets.observation,
                &config.sockets.issuer,
                &config.sockets.checkpoint,
            ]
            .into_iter()
            .chain(config.sockets.device_frontier.iter())
            .chain(config.sockets.notes_frontier.iter())
            .any(|path| path == &text.socket_path)
                || learning
                    .as_ref()
                    .is_some_and(|lane| lane.path() == text.socket_path)
            {
                return Err(io::Error::other("text UI requires a distinct private lane"));
            }
            // A refused one-shot handoff must return before either serving
            // loop starts. All native launch and human registration work is
            // already complete; only the original accept barrier follows.
            let ready = || {
                ready()?;
                if let Some(admin) = &root_admin {
                    admin.activate()?;
                }
                Ok(())
            };
            let bound = listeners::bind_runtime_lanes(&config, ready)?;
            let serve = || {
                learning::serve_optional(
                    learning.as_ref(),
                    &service,
                    &config,
                    &registration,
                    &owner_pidfd,
                    || {
                        std::thread::scope(|scope| {
                            let worker = scope.spawn(|| {
                                service.serve_text_ui(
                                    &text,
                                    &ui_pidfd,
                                    &owner_pidfd,
                                    std::time::Duration::from_millis(config.timeout_ms),
                                    std::time::Duration::from_millis(config.lifetime_ms),
                                )
                            });
                            let original = listeners::serve_bound_lanes(
                                &service,
                                &config,
                                &registration,
                                &owner_pidfd,
                                bound,
                            );
                            let ui = worker
                                .join()
                                .map_err(|_| io::Error::other("text UI lane panicked"))?;
                            original.and(ui)
                        })
                    },
                )
            };
            match &root_admin {
                Some(admin) => admin.run(&service, &config, &registration, &owner_pidfd, serve),
                None => serve(),
            }
        } else {
            let serve = || {
                learning::serve_optional(
                    learning.as_ref(),
                    &service,
                    &config,
                    &registration,
                    &owner_pidfd,
                    || {
                        listeners::serve_lanes_with_ready(
                            &service,
                            &config,
                            &registration,
                            &owner_pidfd,
                            || {
                                ready()?;
                                if let Some(admin) = &root_admin {
                                    admin.activate()?;
                                }
                                Ok(())
                            },
                        )
                    },
                )
            };
            match &root_admin {
                Some(admin) => admin.run(&service, &config, &registration, &owner_pidfd, serve),
                None => serve(),
            }
        }
    }
}

