//! One original task export retains the same session for Material and V3.
//! No owner, task, runtime, clock or live capability leaves this private tree.

use std::sync::Arc;
use std::time::Instant;
use std::os::fd::OwnedFd;
use std::os::unix::net::UnixStream;
use std::path::Path;

use codex_hepta_neuron::FileAnchorWitnessStore;

use super::{OriginalHostInitialOperation, OriginalRootCircuitTaskCustodyV1,
    PreparedHostAuthoritySession, PreparedRootHostCircuitTaskV1,
    PreparedRootMaterialSourceHostV1, require_original_session};
use crate::AgentdError;
use crate::authority_host_runtime::{OriginalTaskResidentPrepared,
    OriginalTaskResidentInputs, OriginalTaskResidentPaths, OriginalTaskResidentPurpose,
    OriginalTaskPrefreezeState};
use crate::neuron_generation_current::NeuronGenerationInitialReadbackV1;

pub(crate) struct OriginalLoadedTaskFollowups {
    session: Arc<PreparedHostAuthoritySession>,
    operation: Arc<OriginalHostInitialOperation>,
    custody: Arc<OriginalRootCircuitTaskCustodyV1<FileAnchorWitnessStore, FileAnchorWitnessStore>>,
    end: Instant,
}

impl PreparedRootHostCircuitTaskV1<FileAnchorWitnessStore, FileAnchorWitnessStore> {
    pub(crate) fn take_original_loader_followups(&mut self) -> Result<(
        PreparedRootMaterialSourceHostV1<FileAnchorWitnessStore, FileAnchorWitnessStore>,
        OriginalLoadedTaskFollowups,
    ), AgentdError> {
        // The existing single-use bit is consumed by the original exporter.
        // Failure does not return it, the task lane, or a fresh execution right.
        let material = PreparedRootHostCircuitTaskV1::prepare_original_material_source_host(self)?;
        let followups = OriginalLoadedTaskFollowups {
            session: Arc::clone(&self.session), operation: Arc::clone(&self.operation),
            custody: Arc::clone(&self.custody), end: self.end,
        };
        followups.require_original_task_followups()?;
        Ok((material, followups))
    }
}

impl OriginalLoadedTaskFollowups {
    pub(crate) fn require_original_task_followups(&self) -> Result<(), AgentdError> {
        require_original_session(&self.session, self.end)?;
        let observed = OriginalRootCircuitTaskCustodyV1::read_original_operation(&self.custody)?;
        if !matches!(observed, NeuronGenerationInitialReadbackV1::Published(_)) {
            return Err(AgentdError::Invalid("the original task generation is not Published".into()));
        }
        OriginalHostInitialOperation::require_observed(&self.operation, &observed)?;
        require_original_session(&self.session, self.end)
    }

    pub(crate) fn prepare_resident(
        &self, paths: OriginalTaskResidentPaths, original: OriginalTaskResidentInputs,
        prefreeze: &OriginalTaskPrefreezeState, purpose: OriginalTaskResidentPurpose, startup_end: Instant,
    ) -> Result<OriginalTaskResidentPrepared, AgentdError> {
        self.require_original_task_followups()?;
        let prepared = crate::authority_host_runtime::prepare_original_task_resident(
            &self.session.service, &self.session.config, &self.session.registration,
            &self.custody, paths, original, prefreeze, purpose, startup_end.min(self.end), self.end,
        )?;
        self.require_original_task_followups()?;
        Ok(prepared)
    }

    pub(crate) fn prepare_prefreeze(
        &self, disclosure_file: &Path, evidence_file: &Path,
        stream: UnixStream, original_material_pidfd: OwnedFd, startup_end: Instant,
    ) -> Result<(crate::OriginalRootPrefreezeSourceRegistrationV1, OriginalTaskPrefreezeState), AgentdError> {
        self.require_original_task_followups()?;
        let original = crate::authority_host_runtime::prepare_original_task_prefreeze(
            &self.session.config, &self.session.registration, disclosure_file, evidence_file,
            stream, original_material_pidfd, startup_end.min(self.end),
        )?;
        self.require_original_task_followups()?;
        Ok(original)
    }

    pub(crate) fn require_startup_end(&self, requested: Instant) -> Result<Instant, AgentdError> {
        self.require_original_task_followups()?;
        Ok(requested.min(self.end))
    }
}

//! Root-protected disclosure configuration exists before A. It contains no
//! RunStart, Decision, Source result, completed receipt or Dataset freeze.
//! The actual owner must still authenticate every Source/Cell observation.

use std::os::fd::OwnedFd;
use std::os::unix::net::UnixStream;
use std::path::{Path, PathBuf};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

use base64::Engine;
use base64::engine::general_purpose::STANDARD_NO_PAD;
use codex_hepta_learning_ledger::{LearningEvidenceRoleV1, SignedLearningEvidenceV1,
    TrustedLearningSignerV1};
use codex_hepta_neuron::{CellCandidateMaskV1, CellScopeV1};
use codex_hepta_types::StableId;
use serde::Deserialize;

use super::{protocol, trust, wire};
use crate::{AgentdError, AgentdRootAuthorityPeer, CircuitTaskSourceInputV1,
    OriginalCellQ24MaterialReceiptConfigV1, OriginalCircuitPrefreezeSourceRequestV1,
    OriginalRootPrefreezeSourceRegistrationV1};
use crate::authority_host_config::{HostAuthorityRegistration, read_root_json};
use crate::HostAuthorityServiceConfig;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DisclosureFile {
    schema_version: u32,
    purpose: String,
    generation_operation_id: String,
    generation_intent_digest: String,
    task_digest: String,
    source: SourceInput,
    ledger_binding_digest: String,
    trust_root: PathBuf,
    signed_distribution: PathBuf,
    trust: trust::OriginalDistributionPin,
    generator_actor: String,
    experience_actor: String,
    dataset_actor: String,
    consumer: Consumer,
    nonce: [u8; 16],
    evidence: GeneratorEvidence,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Consumer {
    uid: u32, gid: u32, pid: u32, boot_id: String, process_start_ticks: u64,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct SourceInput {
    agent_id: String, cell_id: String, run_id: String,
    principal_digest: String, source_frontier: String, objective_digest: String,
    ndu_snapshot_digest: String, monotonic_micros: u64, deadline_micros: u64,
    observation: Vec<u8>, candidates: Vec<Candidate>, lease_duration_ms: u64,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Candidate { candidate_id: String, allowed: bool }

impl SourceInput {
    fn original(self) -> Result<CircuitTaskSourceInputV1, AgentdError> {
        Ok(CircuitTaskSourceInputV1 {
            scope: CellScopeV1 {
                agent_id: StableId::new(self.agent_id).map_err(protocol)?,
                cell_id: StableId::new(self.cell_id).map_err(protocol)?,
                run_id: StableId::new(self.run_id).map_err(protocol)?,
                principal_digest: trust::digest(&self.principal_digest)?,
            },
            source_frontier: trust::digest(&self.source_frontier)?,
            objective_digest: trust::digest(&self.objective_digest)?,
            ndu_snapshot_digest: trust::digest(&self.ndu_snapshot_digest)?,
            monotonic_micros: self.monotonic_micros, deadline_micros: self.deadline_micros,
            observation: self.observation,
            candidates: self.candidates.into_iter().map(|candidate| {
                Ok(CellCandidateMaskV1 {
                    candidate_id: StableId::new(candidate.candidate_id).map_err(protocol)?,
                    allowed: candidate.allowed,
                })
            }).collect::<Result<_, AgentdError>>()?,
            lease_duration_ms: self.lease_duration_ms,
        })
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GeneratorEvidence {
    evidence_id: String, principal_id: String, trust_digest: String,
    scope_digest: String, objective_digest: String, authority_epoch: u64,
    issued_at: u64, expires_at: u64, payload_digest: String, signature: String,
}

impl GeneratorEvidence {
    fn original(self) -> Result<SignedLearningEvidenceV1, AgentdError> {
        let signature = STANDARD_NO_PAD.decode(&self.signature).map_err(protocol)?;
        if signature.len() != 64 || STANDARD_NO_PAD.encode(&signature) != self.signature {
            return Err(protocol("original disclosure signature encoding differs"));
        }
        Ok(SignedLearningEvidenceV1 {
            evidence_id: StableId::new(self.evidence_id).map_err(protocol)?,
            principal_id: StableId::new(self.principal_id).map_err(protocol)?,
            role: LearningEvidenceRoleV1::Generator,
            trust_digest: trust::digest(&self.trust_digest)?,
            scope_digest: trust::digest(&self.scope_digest)?,
            objective_digest: trust::digest(&self.objective_digest)?,
            authority_epoch: self.authority_epoch, issued_at: self.issued_at,
            expires_at: self.expires_at, payload_digest: trust::digest(&self.payload_digest)?,
            signature: signature.try_into().map_err(|_| protocol("original disclosure signature width differs"))?,
        })
    }
}

/// Private retained data joins the pre-A enrollment to the later signed
/// Material configuration. This is not a public reader or a Source owner.
pub(crate) struct OriginalTaskPrefreezeState {
    trust: trust::OriginalSourceTrust,
    source: CircuitTaskSourceInputV1,
    experience: TrustedLearningSignerV1,
    dataset: TrustedLearningSignerV1,
}

pub(crate) fn prepare_original_task_prefreeze(
    config: &HostAuthorityServiceConfig, original: &HostAuthorityRegistration,
    disclosure_file: &Path, trusted_evidence: &Path,
    stream: UnixStream, original_consumer_pidfd: OwnedFd, startup_end: Instant,
) -> Result<(OriginalRootPrefreezeSourceRegistrationV1, OriginalTaskPrefreezeState), AgentdError> {
    wire::remaining(startup_end)?;
    let value: DisclosureFile = read_root_json(disclosure_file)?;
    if value.schema_version != 1
        || value.purpose != "hepta.root.original-task-prefreeze-disclosure.v1"
        || matches!(value.consumer.uid, 0 | u32::MAX)
        || matches!(value.consumer.gid, 0 | u32::MAX)
        || value.consumer.pid == original.peer_pid || value.consumer.pid == std::process::id()
        || value.nonce == [0; 16] || config.peer_uid == 0
    { return Err(protocol("protected original pre-freeze disclosure differs")); }
    let at = now()?;
    let trust = trust::OriginalSourceTrust::read_original_signed_distribution(trusted_evidence, &value.trust_root,
        &value.signed_distribution, &value.trust, at)?;
    let generator = trust.original_signer(&StableId::new(value.generator_actor).map_err(protocol)?,
        LearningEvidenceRoleV1::Generator, at)?;
    let experience = trust.original_signer(&StableId::new(value.experience_actor).map_err(protocol)?,
        LearningEvidenceRoleV1::Observer, at)?;
    let dataset = trust.original_signer(&StableId::new(value.dataset_actor).map_err(protocol)?,
        LearningEvidenceRoleV1::Observer, at)?;
    let consumer = AgentdRootAuthorityPeer { pid: value.consumer.pid,
        boot_id: value.consumer.boot_id, process_start_ticks: value.consumer.process_start_ticks };
    wire::Process::require_original(&wire::Process::from_peer(&consumer))?;
    crate::authority_host_runtime::verify_process_credentials(consumer.pid, value.consumer.uid, value.consumer.gid)?;
    crate::root_production_handoff::require_original_resident_process_pin(&original_consumer_pidfd, consumer.pid)?;
    let activated = trust.original_activation();
    let source = value.source.original()?;
    let request = OriginalCircuitPrefreezeSourceRequestV1 {
        generation_operation_id: value.generation_operation_id,
        generation_intent_digest: trust::digest(&value.generation_intent_digest)?,
        task_digest: trust::digest(&value.task_digest)?, source: source.clone(),
        ledger_binding_digest: trust::digest(&value.ledger_binding_digest)?,
        evidence_trust_digest: activated.verifier().trust_digest(),
        trust_distribution_digest: activated.distribution_digest(), trust_generation: activated.generation(),
        generator, experience_signer: experience.clone(), dataset_signer: dataset.clone(),
        consumer, consumer_uid: value.consumer.uid, nonce: value.nonce,
    };
    // The same fixed request is authenticated below, before its stream can be
    // served. Root's file authorizes disclosure; the Generator cannot choose a
    // different task, recipient or trust by sending a different signed request.
    let registration = OriginalRootPrefreezeSourceRegistrationV1::from_original_supervisor(
        request, activated, value.evidence.original()?, original_consumer_pidfd, stream, startup_end,
    )?;
    trust.require_original_distribution_window(now()?)?;
    wire::remaining(startup_end)?;
    Ok((registration, OriginalTaskPrefreezeState { trust, source, experience, dataset }))
}

impl OriginalTaskPrefreezeState {
    pub(crate) fn require_original_prefreeze_trust(&self) -> Result<(), AgentdError> {
        self.trust.require_original_distribution_window(now()?)?;
        Ok(())
    }

    pub(super) fn evidence(&self) -> &trust::OriginalHostTrust { &self.trust.evidence }

    pub(super) fn require_material(&self, material: &OriginalCellQ24MaterialReceiptConfigV1)
        -> Result<(), AgentdError>
    {
        self.trust.require_original_distribution_window(now()?)?;
        let initial = &material.initial;
        if material.verifier.trust_digest() != self.trust.evidence.verifier.trust_digest()
            || material.experience_signer != self.experience || material.dataset_signer != self.dataset
            || initial.owners.experience != self.experience.principal.principal_id
            || initial.owners.dataset != self.dataset.principal.principal_id
            || initial.owners.evidence_trust_digest != self.trust.evidence.verifier.trust_digest()
            || initial.request.agent_id != self.source.scope.agent_id
            || initial.request.cell_id != self.source.scope.cell_id
            || initial.request.source_run_id != self.source.scope.run_id
            || initial.request.principal_id.as_str() != self.source.scope.principal_digest.to_string()
            || initial.request.envelope.objective_digest != self.source.objective_digest
        { return Err(protocol("late Material differs from the original pre-freeze enrollment")); }
        Ok(())
    }
}

fn now() -> Result<u64, AgentdError> {
    Ok(SystemTime::now().duration_since(UNIX_EPOCH).map_err(protocol)?.as_secs())
}

//! Existing Root-pinned learning trust for the fixed Source disclosure.
//! Activation verifies the original signed distribution; it neither rotates
//! the ledger nor creates a root, signer, grant or replacement trust history.

use std::io;
use std::path::Path;

use base64::Engine;
use base64::engine::general_purpose::STANDARD_NO_PAD;
use codex_hepta_learning_ledger::{ActivatedLearningTrustV1, LearningEvidenceRoleV1,
    LearningEvidenceTrustV1, LearningTrustDistributionV1, LearningTrustRootV1,
    SignedLearningTrustDistributionV1, TrustedLearningSignerV1, activate_learning_trust};
use codex_hepta_types::StableId;
use serde::Deserialize;

use super::{OriginalHostTrust, digest};
use crate::authority_host_config::read_root_json;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(in super::super) struct OriginalDistributionPin {
    root_id: String,
    root_digest: String,
    distribution_id: String,
    distribution_digest: String,
    generation: u64,
    evidence_trust_digest: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RootFile {
    schema_version: u32,
    purpose: String,
    root_id: String,
    scope_digest: String,
    verifying_key: [u8; 32],
    valid_from: u64,
    expires_at: u64,
    revoked_at: Option<u64>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DistributionFile {
    schema_version: u32,
    purpose: String,
    distribution_id: String,
    generation: u64,
    effective_at: u64,
    root_id: String,
    issued_at: u64,
    expires_at: u64,
    signature: String,
}

pub(in super::super) struct OriginalSourceTrust {
    pub(in super::super) evidence: OriginalHostTrust,
    root: LearningTrustRootV1,
    signed: SignedLearningTrustDistributionV1,
    activated: ActivatedLearningTrustV1,
}

impl OriginalSourceTrust {
    pub(in super::super) fn read_original_signed_distribution(
        evidence_path: &Path, root_path: &Path, distribution_path: &Path,
        pin: &OriginalDistributionPin, at: u64,
    ) -> io::Result<Self> {
        let evidence = OriginalHostTrust::read(evidence_path)?;
        let root: RootFile = read_root_json(root_path)?;
        let signed: DistributionFile = read_root_json(distribution_path)?;
        if root.schema_version != 1 || root.purpose != "hepta.root.learning-trust-root.v1"
            || signed.schema_version != 1
            || signed.purpose != "hepta.root.original-learning-trust-distribution.v1"
        { return Err(io::Error::other("original learning trust purpose differs")); }
        let root = LearningTrustRootV1 {
            root_id: StableId::new(root.root_id).map_err(io::Error::other)?,
            scope_digest: digest(&root.scope_digest)?, verifying_key: root.verifying_key,
            valid_from: root.valid_from, expires_at: root.expires_at, revoked_at: root.revoked_at,
        };
        let signature = STANDARD_NO_PAD.decode(&signed.signature).map_err(io::Error::other)?;
        if signature.len() != 64 || STANDARD_NO_PAD.encode(&signature) != signed.signature {
            return Err(io::Error::other("original distribution signature encoding differs"));
        }
        let signed = SignedLearningTrustDistributionV1 {
            distribution: LearningTrustDistributionV1 {
                distribution_id: StableId::new(signed.distribution_id).map_err(io::Error::other)?,
                generation: signed.generation, effective_at: signed.effective_at,
                trust: LearningEvidenceTrustV1 {
                    scope_digest: evidence.verifier.scope_digest(),
                    objective_digest: evidence.verifier.objective_digest(),
                    authority_epoch: evidence.verifier.authority_epoch(),
                    signers: evidence.signers.clone(),
                },
            },
            root_id: StableId::new(signed.root_id).map_err(io::Error::other)?,
            issued_at: signed.issued_at, expires_at: signed.expires_at,
            signature: signature.try_into().map_err(|_| io::Error::other("original signature width differs"))?,
        };
        // None here validates one already selected immutable distribution. It
        // is not a request to advance an existing ledger's trust generation.
        let activated = activate_learning_trust(&root, signed.clone(), None, at)
            .map_err(io::Error::other)?;
        if activated.root_id().as_str() != pin.root_id
            || activated.root_digest() != digest(&pin.root_digest)?
            || activated.distribution_id().as_str() != pin.distribution_id
            || activated.distribution_digest() != digest(&pin.distribution_digest)?
            || activated.generation() != pin.generation
            || activated.verifier().trust_digest() != digest(&pin.evidence_trust_digest)?
            || activated.verifier().trust_digest() != evidence.verifier.trust_digest()
        { return Err(io::Error::other("original protected trust pins differ")); }
        Ok(Self { evidence, root, signed, activated })
    }

    pub(in super::super) fn require_original_distribution_window(&self, at: u64) -> io::Result<()> {
        let actual = activate_learning_trust(&self.root, self.signed.clone(), None, at)
            .map_err(io::Error::other)?;
        if actual.root_id() != self.activated.root_id()
            || actual.root_digest() != self.activated.root_digest()
            || actual.distribution_id() != self.activated.distribution_id()
            || actual.distribution_digest() != self.activated.distribution_digest()
            || actual.generation() != self.activated.generation()
            || actual.verifier().trust_digest() != self.evidence.verifier.trust_digest()
        { return Err(io::Error::other("original immutable trust changed")); }
        Ok(())
    }

    pub(in super::super) fn original_activation(&self) -> ActivatedLearningTrustV1 {
        self.activated.clone()
    }

    pub(in super::super) fn original_signer(
        &self, actor: &StableId, role: LearningEvidenceRoleV1, at: u64,
    ) -> io::Result<TrustedLearningSignerV1> {
        self.require_original_distribution_window(at)?;
        let signer = self.evidence.signers.iter()
            .find(|value| &value.principal.principal_id == actor)
            .ok_or_else(|| io::Error::other("original disclosed actor is not enrolled"))?;
        self.evidence.verifier.require_signer_binding(role, signer, at).map_err(io::Error::other)?;
        Ok(signer.clone())
    }
}

//! The existing V3 registration is opened on the task's SAME retained Root
//! service. Its late signed Material must match the earlier fixed disclosure
//! and uses that same evidence trust; no second Source lane is constructed.

use super::*;
use std::path::PathBuf;
use std::time::Instant;
use codex_hepta_neuron::FileAnchorWitnessStore;
use crate::{AgentdError, HostAuthorityService, OriginalRootCircuitTaskCustodyV1,
    RootCandidateStageHandoffV1};
use crate::authority_host_config::HostAuthorityRegistration;

#[path = "authority_host_task_prefreeze_inputs.rs"]
mod prefreeze;
pub(crate) use prefreeze::{OriginalTaskPrefreezeState, prepare_original_task_prefreeze};

pub(crate) struct OriginalTaskResidentPaths {
    pub(crate) deployment: PathBuf,
}

pub(crate) enum OriginalTaskResidentPurpose {
    Fresh,
    Readback(PathBuf),
}

pub(crate) struct OriginalTaskResidentInputs {
    pub(crate) stage_transport: crate::root_production_handoff::OriginalRootCandidateStageTransportV1,
    pub(crate) enrollment_handoff: UnixDatagram,
    pub(crate) original_root_pidfd: OwnedFd,
    pub(crate) original_consumer_pidfd: OwnedFd,
    pub(crate) baseline_files: CellQ24ModelFilesV1,
}

pub(crate) struct OriginalTaskResidentPrepared {
    registration: RootResidentLearningRegistrationV3,
    inputs: crate::RootResidentCandidateInputsV1,
    handoff: RootCandidateStageHandoffV1,
    listener: ResidentListener,
    packet: wire::Packet,
    enrollment_handoff: UnixDatagram,
    original_root_pidfd: OwnedFd,
    original_consumer_pidfd: OwnedFd,
    peer: crate::AgentdRootAuthorityPeer,
    uid: u32,
    timeout: Duration,
    connect_end: Instant,
    session_end: Instant,
}

/// Crate-private fixed assembly. It accepts the concrete retained task custody,
/// never a caller checker or a decoded Source/Cell receipt. Root's old issuer
/// factory is deliberately absent: the provided service already owns it.
pub(crate) fn prepare_original_task_resident(
    service: &HostAuthorityService, config: &HostAuthorityServiceConfig,
    original_registration: &HostAuthorityRegistration,
    custody: &OriginalRootCircuitTaskCustodyV1<FileAnchorWitnessStore, FileAnchorWitnessStore>,
    paths: OriginalTaskResidentPaths, original: OriginalTaskResidentInputs,
    prefreeze: &OriginalTaskPrefreezeState,
    purpose: OriginalTaskResidentPurpose, startup_end: Instant, task_end: Instant,
) -> Result<OriginalTaskResidentPrepared, AgentdError> {
    wire::remaining(startup_end)?;
    prefreeze.require_original_prefreeze_trust()?;
    let trust = prefreeze.evidence();
    let OriginalTaskResidentInputs { stage_transport, enrollment_handoff, original_root_pidfd,
        original_consumer_pidfd, baseline_files } = original;
    let baseline = Arc::new(LoadedCellQ24ModelV1::open_files(baseline_files).map_err(protocol)?);
    let inputs::OriginalDeployment { profile, inputs, consumer, handoff_timeout, enrollment_profile } =
        inputs::OriginalDeployment::read(&paths.deployment, trust, baseline)?;
    prefreeze.require_material(&inputs.material)?;
    let (peer, uid, requested_timeout, lifetime) = consumer.into_peer();
    if uid != config.peer_uid || matches!(config.peer_gid, 0 | u32::MAX)
        || peer.pid != original_registration.peer_pid
        || peer.boot_id != original_registration.boot_id
        || peer.process_start_ticks != original_registration.process_start_ticks
    { return Err(protocol("resident recipient is not this original registered daemon")); }
    let timeout = requested_timeout.min(Duration::from_millis(config.timeout_ms.min(500)));
    if timeout.is_zero() { return Err(protocol("original resident command timeout is empty")); }
    let recipient = wire::Process::from_peer(&peer);
    wire::Process::require_original(&recipient)?;
    crate::authority_host_runtime::verify_process_credentials(peer.pid, uid, config.peer_gid)?;
    crate::root_production_handoff::require_original_resident_process_pin(&original_consumer_pidfd, peer.pid)?;
    let connect_end = (Instant::now() + handoff_timeout).min(startup_end).min(task_end);
    let session_end = (Instant::now() + lifetime).min(task_end);
    wire::remaining(connect_end)?;
    let (authorization, readback) = match purpose {
        OriginalTaskResidentPurpose::Fresh => (wire::Authorization::Fresh, None),
        OriginalTaskResidentPurpose::Readback(path) => {
            let value: ReadbackFile = read_root_json(&path)?;
            if value.schema_version != 3 || value.purpose != "hepta.host-resident-learning.readback-deployment.v3" {
                return Err(protocol("original resident readback purpose differs"));
            }
            let authorization = wire::Authorization::Readback { intent: value.intent.clone(), lease: value.lease.clone() };
            let readback = RootResidentLearningReadbackAuthorizationV3::from_original_root(
                &profile, value.intent, value.lease)?;
            (authorization, Some(readback))
        }
    };
    let handoff = stage_transport.bind_original_profile(&profile)?;
    wire::remaining(connect_end)?;
    // A protected configuration and signed freeze do not prove A ran. Reach
    // the retained original Source and same-Arc Cell before any registration.
    let _actual_source = OriginalRootCircuitTaskCustodyV1::read_original_material_source(
        custody, &inputs.material.initial.request)?;
    prefreeze.require_material(&inputs.material)?;
    wire::remaining(connect_end)?;
    let binding = profile.binding();
    let registration = match readback {
        Some(readback) => HostAuthorityService::recover_resident_learning_v3(service, profile, readback)?,
        None => HostAuthorityService::register_resident_learning_v3(service, profile)?,
    };
    wire::remaining(connect_end)?;
    let listener: ResidentListener = ResidentListener::bind_original(config, binding)?;
    let (path, device, inode) = listener.original_node();
    // Read monotonic first. Subsequent Instant sampling can only reduce each
    // transmitted remainder; neither deadline is reset by enrollment.
    let now_ns = wire::now_ns()?;
    let connect_before_ns = now_ns.checked_add(u64::try_from(wire::remaining(connect_end)?.as_nanos()).map_err(protocol)?)
        .ok_or_else(|| protocol("original resident connect deadline overflow"))?;
    let session_end_ns = now_ns.checked_add(u64::try_from(wire::remaining(session_end)?.as_nanos()).map_err(protocol)?)
        .ok_or_else(|| protocol("original resident session deadline overflow"))?;
    let packet = wire::Packet { schema_version: 3, purpose: wire::PURPOSE.into(),
        root: wire::Process::current()?, consumer: recipient, consumer_uid: uid, consumer_gid: config.peer_gid,
        profile: enrollment_profile, trusted_evidence: String::from_utf8(trust.encoded.clone()).map_err(protocol)?,
        socket: path.clone(), socket_device: device, socket_inode: inode,
        connect_before_ns, session_end_ns, command_timeout_ms: u64::try_from(timeout.as_millis()).map_err(protocol)?,
        authorization };
    wire::remaining(connect_end)?;
    prefreeze.require_original_prefreeze_trust()?;
    Ok(OriginalTaskResidentPrepared { registration, inputs, handoff, listener, packet,
        enrollment_handoff, original_root_pidfd, original_consumer_pidfd, peer, uid, timeout,
        connect_end, session_end })
}

impl OriginalTaskResidentPrepared {
    pub(crate) async fn enroll(self) -> Result<RootResidentCandidateEnrollmentServiceV3, AgentdError> {
        let Self { registration, inputs, handoff, listener, packet, enrollment_handoff,
            original_root_pidfd, original_consumer_pidfd, peer, uid, timeout, connect_end, session_end } = self;
        wire::remaining(connect_end)?;
        let sealed = wire::seal(&packet)?;
        crate::root_production_handoff::send_original_resident_enrollment(
            enrollment_handoff, &sealed, &original_root_pidfd, wire::remaining(connect_end)?)?;
        let (stream, socket_guard) = listener.accept_original(connect_end).await?;
        wire::Process::require_original(&packet.consumer)?;
        crate::authority_host_runtime::verify_process_credentials(peer.pid, uid, packet.consumer_gid)?;
        crate::root_production_handoff::require_original_resident_process_pin(&original_consumer_pidfd, peer.pid)?;
        wire::remaining(connect_end)?;
        let service = RootResidentLearningRegistrationV3::into_candidate_service(registration, inputs, handoff,
            RootResidentLearningConsumerV3 { stream, peer, uid, original_consumer_pidfd,
                timeout, lifetime: wire::remaining(session_end)? }).map_err(protocol)?;
        wire::remaining(connect_end)?;
        Ok(RootResidentCandidateEnrollmentServiceV3 { service, socket_guard, session_end })
    }
}

fn protocol(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::Protocol(format!("same-session original resident assembly: {error}"))
}

//! Explicit Root administration, fresh publication and open-only session entry.

#[cfg(target_os = "linux")]
#[path = "../authority_host_resident_cli.rs"]
mod resident_cli;
#[cfg(target_os = "linux")]
#[path = "../authority_host_resident_enrollment_cli.rs"]
mod resident_enrollment_cli;
#[cfg(target_os = "linux")]
#[path = "../authority_host_loaded_task_cli.rs"]
mod loaded_task_cli;

#[cfg(target_os = "linux")]
fn main() -> Result<(), Box<dyn std::error::Error>> {
    use std::os::fd::AsFd;
    use std::path::PathBuf;
    let mut args = std::env::args_os().skip(1);
    let command = args
        .next()
        .ok_or("initialize, register-writer, register-learning, serve-session, serve-fresh-session, diagnose-native, launch-native, provider-status or provider-login required")?;
    let mut options = std::collections::BTreeMap::new();
    let mut pidfd_stdin = false;
    while let Some(option) = args.next() {
        if option == "--owner-pidfd-stdin" {
            if pidfd_stdin {
                return Err("duplicate owner pidfd option".into());
            }
            pidfd_stdin = true;
        } else {
            let value = args.next().ok_or("missing option value")?;
            if options.insert(option, value).is_some() {
                return Err("duplicate option".into());
            }
        }
    }
    if command == "serve-original-task-learning" || command == "recover-original-task-learning" {
        if pidfd_stdin {
            return Err("original task loading requires all named original descriptors".into());
        }
        let purpose = if command == "serve-original-task-learning" {
            loaded_task_cli::Command::Fresh
        } else {
            loaded_task_cli::Command::Recover
        };
        return loaded_task_cli::run(options, purpose);
    }
    if command == "serve-resident-learning-late" || command == "recover-resident-learning-late" {
        if pidfd_stdin {
            return Err("late resident service requires its named original pidfds".into());
        }
        let purpose = if command == "serve-resident-learning-late" {
            resident_enrollment_cli::Command::Fresh
        } else {
            resident_enrollment_cli::Command::Recover
        };
        return resident_enrollment_cli::run(options, purpose);
    }
    if command == "serve-resident-learning" || command == "recover-resident-learning" {
        if pidfd_stdin {
            return Err("resident service requires its named original consumer pidfd".into());
        }
        let purpose = if command == "serve-resident-learning" {
            resident_cli::Command::Fresh
        } else {
            resident_cli::Command::Recover
        };
        return resident_cli::run(options, purpose);
    }
    let mut take = |key: &str| {
        options
            .remove(std::ffi::OsStr::new(key))
            .map(PathBuf::from)
            .ok_or("missing required option")
    };
    if command == "provider-status" || command == "provider-login" {
        let route = take("--route")?;
        if !options.is_empty() || pidfd_stdin {
            return Err("provider command accepts only the original --route file".into());
        }
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()?;
        let result = if command == "provider-status" {
            runtime
                .block_on(codex_hepta_agentd::text_session::diagnose_existing_provider(&route))?
        } else {
            runtime.block_on(codex_hepta_agentd::text_session::login_existing_provider(
                &route,
                |challenge| {
                    // Only the original one-time login challenge is displayed.
                    // No credential file, token, email or account ID is printed.
                    if let Ok(json) = serde_json::to_string(&challenge) {
                        println!("{json}");
                    }
                },
            ))?
        };
        println!("{}", serde_json::to_string(&result)?);
    } else if command == "diagnose-native" || command == "launch-native" {
        let config = take("--config")?;
        let registration = take("--registration")?;
        let profile = take("--native-profile")?;
        if !options.is_empty() || !pidfd_stdin {
            return Err("existing config, registration, native profile and pre-held owner pidfd are required".into());
        }
        let owner = std::io::stdin().as_fd().try_clone_to_owned()?;
        if command == "diagnose-native" {
            println!(
                "{}",
                serde_json::to_string(&codex_hepta_agentd::diagnose_native_launch(
                    &config,
                    &registration,
                    &profile,
                    &owner
                )?)?
            );
        } else {
            codex_hepta_agentd::launch_host_authority_native_session(
                &config,
                &registration,
                &profile,
                owner,
            )?;
        }
    } else if command == "initialize" {
        let state = take("--state")?;
        let bootstrap = take("--bootstrap")?;
        if !options.is_empty() || pidfd_stdin {
            return Err("unknown initialize option".into());
        }
        let initialized = codex_hepta_agentd::initialize_host_authority(&state, &bootstrap)?;
        println!("{}", serde_json::to_string(&initialized)?);
    } else if command == "register-writer" {
        let config = take("--config")?;
        if !options.is_empty() || pidfd_stdin {
            return Err("unknown register-writer option".into());
        }
        let proof = codex_hepta_agentd::register_host_writer_authorization(&config)?;
        println!("{}", serde_json::to_string(&proof)?);
    } else if command == "register-learning" {
        let config = take("--config")?;
        let registration = take("--registration")?;
        let profile = take("--learning-profile")?;
        if !options.is_empty() || !pidfd_stdin {
            return Err("learning registration requires original config, registration, Root profile and pre-held owner pidfd".into());
        }
        let owner = std::io::stdin().as_fd().try_clone_to_owned()?;
        let registered = codex_hepta_agentd::register_host_learning_checkpoint(
            &config,
            &registration,
            &profile,
            &owner,
        )?;
        println!("{}", serde_json::to_string(&registered)?);
    } else if command == "serve-session" || command == "serve-fresh-session" {
        let config = take("--config")?;
        let registration = take("--registration")?;
        let text_file = options
            .remove(std::ffi::OsStr::new("--text-ui-registration"))
            .map(PathBuf::from);
        let native_profile = options
            .remove(std::ffi::OsStr::new("--native-profile"))
            .map(PathBuf::from);
        let ui_fd = options.remove(std::ffi::OsStr::new("--text-ui-pidfd"));
        let handoff = options.remove(std::ffi::OsStr::new("--root-handoff-fd"));
        let root_fd = options.remove(std::ffi::OsStr::new("--root-pidfd"));
        let learning_profile = options
            .remove(std::ffi::OsStr::new("--learning-profile"))
            .map(PathBuf::from);
        let learning_handoff = options.remove(std::ffi::OsStr::new("--root-learning-handoff-fd"));
        let notes_profile = options
            .remove(std::ffi::OsStr::new("--notes-launch-profile"))
            .map(PathBuf::from);
        let notes_reservation = options.remove(std::ffi::OsStr::new("--notes-reservation-fd"));
        let notes_session = options.remove(std::ffi::OsStr::new("--notes-session-pidfd"));
        let notes_deployment = options.remove(std::ffi::OsStr::new("--notes-deployment-fd"));
        if !options.is_empty() || !pidfd_stdin {
            return Err("unknown option or missing pre-held owner pidfd".into());
        }
        // Claim every numeric inherited FD before any clone/open/runtime can
        // reuse a missing number. One slot owns each FD and closes the original.
        let mut claimed = std::collections::BTreeSet::new();
        let handoff = handoff
            .as_deref()
            .map(|fd| inherited_descriptor(fd, &mut claimed))
            .transpose()?;
        let root_fd = root_fd
            .as_deref()
            .map(|fd| inherited_descriptor(fd, &mut claimed))
            .transpose()?;
        let learning_handoff = learning_handoff
            .as_deref()
            .map(|fd| inherited_descriptor(fd, &mut claimed))
            .transpose()?;
        if learning_profile.is_some() != learning_handoff.is_some()
            || learning_profile.is_some() && root_fd.is_none()
        {
            return Err("learning serving requires its Root profile, separate handoff and original Root pidfd".into());
        }
        let notes = match (notes_profile, notes_reservation, notes_session, notes_deployment) {
            (None, None, None, None) => None,
            (Some(profile), Some(reservation), Some(session), Some(deployment))
                if command == "serve-fresh-session" => Some((
                    profile, inherited_descriptor(&reservation, &mut claimed)?,
                    inherited_descriptor(&session, &mut claimed)?, inherited_descriptor(&deployment, &mut claimed)?,
                )),
            _ => return Err("fresh Notes requires its complete inherited reservation, Session pidfd, deployment memfd and Root profile".into()),
        };
        let text = match (text_file.as_deref(), ui_fd) {
            (None, None) => None,
            (Some(file), Some(fd)) => Some((file, inherited_descriptor(&fd, &mut claimed)?)),
            _ => {
                return Err("text UI registration and pre-held pidfd are required together".into());
            }
        };
        if native_profile.is_some() && text.is_some() {
            return Err("native child launch and an inherited text UI are exclusive".into());
        }
        let owner = std::io::stdin().as_fd().try_clone_to_owned()?;
        let prepared = if command == "serve-fresh-session" {
            let handoff =
                handoff.ok_or("fresh session requires the original Root handoff descriptor")?;
            let root = root_fd
                .as_ref()
                .ok_or("fresh session requires the pre-held current Root pidfd")?;
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()?;
            let prepared = runtime.block_on(
                codex_hepta_agentd::PreparedHostAuthoritySession::prepare_fresh_from_registered(
                    &config,
                    &registration,
                    owner,
                ),
            )?;
            let (prepared, consumers) = prepared.handoff_fresh_agent_filesystem()?;
            let prepared = match notes {
                Some((profile, reservation, session, deployment)) => prepared
                    .with_notes_startup_from_session(
                        &profile,
                        std::os::unix::net::UnixDatagram::from(reservation),
                        session,
                        std::fs::File::from(deployment),
                    )?,
                None => prepared,
            };
            let bootstrap = prepared.seal_bootstrap(&consumers)?;
            codex_hepta_agentd::send_root_production_handoff(
                std::os::unix::net::UnixDatagram::from(handoff),
                &bootstrap,
                root,
                std::time::Duration::from_secs(30),
            )?;
            prepared
        } else {
            if handoff.is_some() || root_fd.is_some() && learning_handoff.is_none() {
                return Err("open-only serving does not accept fresh handoff inputs".into());
            }
            codex_hepta_agentd::PreparedHostAuthoritySession::open(&config, &registration, owner)?
        };
        let prepared = match learning_profile {
            Some(profile) => prepared.with_registered_learning(&profile)?,
            None => prepared,
        };
        let learning_bootstrap = learning_handoff
            .as_ref()
            .map(|_| prepared.seal_learning_bootstrap())
            .transpose()?;
        let ready = || {
            if let (Some(handoff), Some(bootstrap), Some(root)) =
                (learning_handoff, learning_bootstrap, root_fd)
            {
                codex_hepta_agentd::send_root_learning_handoff(
                    std::os::unix::net::UnixDatagram::from(handoff),
                    &bootstrap,
                    &root,
                    std::time::Duration::from_secs(30),
                )
                .map_err(std::io::Error::other)?;
            }
            Ok(())
        };
        match (native_profile, text) {
            (Some(profile), None) => {
                prepared.launch_native_with_ready(&config, &registration, &profile, ready)?
            }
            (None, Some((file, pidfd))) => {
                prepared.serve_with_text_and_ready(file, pidfd, ready)?
            }
            (None, None) => prepared.serve_with_ready(ready)?,
            (Some(_), Some(_)) => return Err("exclusive native/text UI options".into()),
        }
    } else {
        return Err("unknown authority command".into());
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn inherited_descriptor(
    value: &std::ffi::OsStr,
    claimed: &mut std::collections::BTreeSet<i32>,
) -> Result<std::os::fd::OwnedFd, Box<dyn std::error::Error>> {
    use std::os::fd::FromRawFd;
    let fd: i32 = value
        .to_str()
        .ok_or("invalid inherited descriptor")?
        .parse()?;
    if fd < 3 || !claimed.insert(fd) {
        return Err(
            "one distinct inherited descriptor numbered at least 3 is required per slot".into(),
        );
    }
    // SAFETY: all numeric descriptors are claimed before any runtime, open or
    // stdin clone. No Rust owner exists for these inherited descriptors yet.
    let flags = unsafe { libc::fcntl(fd, libc::F_GETFD) };
    if flags < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: this is the first and only owner of the checked inherited FD;
    // the per-parse set rejects aliases before a second adoption is possible.
    let descriptor = unsafe { std::os::fd::OwnedFd::from_raw_fd(fd) };
    // SAFETY: the now-owned descriptor remains live across this flags update.
    if unsafe { libc::fcntl(fd, libc::F_SETFD, flags | libc::FD_CLOEXEC) } < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    Ok(descriptor)
}

#[cfg(all(test, target_os = "linux"))]
#[path = "../root_cli_descriptor_tests.rs"]
mod descriptor_tests;

#[cfg(not(target_os = "linux"))]
fn main() {
    eprintln!("hepta-authority-host requires Linux");
    std::process::exit(1);
}

